fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    // If fewer than two elements, we cannot pick a second-largest.
    if s.len() < 2 {
        return None;
    }

    // Initialize max1 and max2 using the first two elements.
    let mut iter = s.iter();
    let first = *iter.next().unwrap();
    let second = *iter.next().unwrap();
    let (mut max1, mut max2) = if first >= second {
        (first, second)
    } else {
        (second, first)
    };

    // Process the rest of the elements.
    for &x in iter {
        if x > max1 {
            // New largest element
            max2 = max1;
            max1 = x;
        } else if x > max2 {
            // New second-largest (possibly equal to max1 if we have duplicates)
            max2 = x;
        }
    }

    Some(max2)
}

